function canWeave(s1: string, s2: string, s3: string): boolean {
  const n = s1.length, m = s2.length;
  if (n + m !== s3.length) return false;
  const dp: boolean[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(false));
  dp[0][0] = true;
  for (let i = 0; i <= n; i++)
    for (let j = 0; j <= m; j++) {
      if (i > 0 && dp[i - 1][j] && s1[i - 1] === s3[i + j - 1]) dp[i][j] = true; // last from s1
      if (j > 0 && dp[i][j - 1] && s2[j - 1] === s3[i + j - 1]) dp[i][j] = true; // last from s2
    }
  return dp[n][m];
}

