function canWeave(s1: string, s2: string, s3: string): boolean {
  const n = s1.length, m = s2.length;
  if (n + m !== s3.length) return false;
  const row: boolean[] = new Array(m + 1).fill(false);
  for (let i = 0; i <= n; i++)
    for (let j = 0; j <= m; j++) {
      if (i === 0 && j === 0) { row[0] = true; continue; }
      const fromS1 = i > 0 && row[j] && s1[i - 1] === s3[i + j - 1];
      const fromS2 = j > 0 && row[j - 1] && s2[j - 1] === s3[i + j - 1];
      row[j] = fromS1 || fromS2;
    }
  return row[m];
}

